struct Breed {
    std::string id; int starting_health{}; std::string attack;
    Monster newMonster() const;                  // single construction path
};
class Monster {
public:
    explicit Monster(const Breed& b) : breed_(b), health_(b.starting_health) {}
    std::string attack() const { return breed_.attack; }   // delegate to the type
private:
    const Breed& breed_;                         // shared type data, not a copy
    int health_;
};
